/**
 * Shop files in the mediashop: served from public/ (supplied) or media-files/ (generated by
 * `pnpm media`) in dev at /media/<slug>/<file>, and copied into dist/mediashop/media/<slug>/
 * after a build. Nothing is generated here: the build never runs pandoc or typst.
 */
import { createReadStream, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import type { AstroIntegration } from 'astro'
import { copyShopFiles, entriesOf, loadOuterMind, mediaType, pieceFile, shopFiles } from '@om/content'

export function shopIntegration(): AstroIntegration {
  return {
    name: 'om-mediashop-files',
    hooks: {
      'astro:server:setup': ({ server }) => {
        server.middlewares.use((req: any, res: any, next: () => void) => {
          const m = decodeURIComponent((req.url ?? '').split('?')[0]).match(/^\/media\/([^/]+)\/([^/]+\.(?:epub|pdf|md|png))$/)
          if (!m) return next()
          const om = loadOuterMind()
          const media = entriesOf(om, 'media').find((x) => x.slug === m[1])
          if (!media) return next()
          const file = shopFiles(om, media).files.find((f) => pieceFile(media.slug, f.piece) === m[2])
          if (!file || !existsSync(file.path)) return next()
          res.setHeader('Content-Type', mediaType(file.path))
          createReadStream(file.path).pipe(res)
        })
      },
      'astro:build:done': ({ dir, logger }) => {
        const om = loadOuterMind()
        const out = fileURLToPath(dir)
        let n = 0
        for (const media of entriesOf(om, 'media')) n += copyShopFiles(om, media, out)
        logger.info(`copied ${n} shop files`)
      },
    },
  }
}
